-- SQLite version of database/schema.sql, used by the integration tests.
CREATE TABLE leads (id INTEGER PRIMARY KEY AUTOINCREMENT, place_id TEXT NOT NULL UNIQUE, nome TEXT NOT NULL DEFAULT '', endereco TEXT NOT NULL DEFAULT '', telefone TEXT NOT NULL DEFAULT '', site TEXT NOT NULL DEFAULT '', nota REAL NOT NULL DEFAULT 0, avaliacoes INTEGER NOT NULL DEFAULT 0, nicho TEXT NOT NULL DEFAULT '', cidade TEXT NOT NULL DEFAULT '', perfil TEXT NOT NULL DEFAULT '', motivos TEXT NOT NULL DEFAULT '', score INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'novo', dono TEXT NULL, criado TEXT NOT NULL);
CREATE TABLE leads_resp (lead_id INTEGER PRIMARY KEY, nome TEXT NOT NULL DEFAULT '', telefone TEXT NOT NULL DEFAULT '', atualizado TEXT NOT NULL);
CREATE TABLE lead_log (id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, usuario TEXT NOT NULL, acao TEXT NOT NULL, detalhe TEXT NULL, criado TEXT NOT NULL);
CREATE TABLE buscas (nicho TEXT NOT NULL, cidade TEXT NOT NULL, pagina INTEGER NOT NULL DEFAULT 0, atualizado TEXT NOT NULL, PRIMARY KEY (nicho, cidade));
CREATE TABLE uso_busca (usuario TEXT NOT NULL, dia TEXT NOT NULL, qtd INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (usuario, dia));
CREATE TABLE senhas (usuario TEXT PRIMARY KEY, hash TEXT NOT NULL, atualizado TEXT NOT NULL);
CREATE TABLE login_tentativas (id INTEGER PRIMARY KEY AUTOINCREMENT, ip TEXT NOT NULL, usuario TEXT NOT NULL, criado TEXT NOT NULL);
